class ListNode {
  constructor(val) {
    this.val = val;
    this.next = null;
  }
}

function getIntersection(headA, headB) {
  let a = headA, b = headB;
  while (a !== b) {
    a = a ? a.next : headB;
    b = b ? b.next : headA;
  }
  return a;
}

const c1 = new ListNode(8), c2 = new ListNode(10);
c1.next = c2;
const a1 = new ListNode(3);
a1.next = c1;
const b1 = new ListNode(4), b2 = new ListNode(6);
b1.next = b2;
b2.next = c1;
console.log(getIntersection(a1, b1).val);

